1	/**
2	 * The whole keyboard map, bound once on the map itself.
3	 *
4	 * Bound once on the page rather than on each tile, so that the same key does the
5	 * same thing wherever you are standing: on a tile, on a chip inside a tile, on a
6	 * row of the panel beside the map, or on nothing at all. A key bound to the tile
7	 * you happen to be on is a key that stops working the moment you press Tab.
8	 *
9	 * **Typing is never a shortcut.** While the keyboard is in a field — naming a
10	 * branch, writing a claim, giving your own number — every key below is left
11	 * alone, because in a field a `j` is a `j`.
12	 *
13	 * | Key | What it does |
14	 * |---|---|
15	 * | `j` / `k` | Down and up the column you are in. No wrapping: wrapping teleports you |
16	 * | `h` / `l` | Back and forward **along a wire** — toward causes, toward effects |
17	 * | `E` | The six things you can do to this claim, in the panel beside the map |
18	 * | `B` | Start a branch from here and name it |
19	 * | `Space` | Flip between the map as it was and the map with your edits |
20	 * | `O` | Read the map as a list |
21	 * | `P` | Show or hide the panel beside the map |
22	 * | `?` | Every key, on one sheet |
23	 * | `⌘K` | Every command, by name |
24	 * | `Escape` | Close whatever is open |
25	 *
26	 * **Every move says what it did.** One line under the map names the last
27	 * keystroke's result — which wire it took, or that there was no wire that way,
28	 * or that you are at the end of a column. A movement you cannot account for is
29	 * the same failure as a number you cannot account for, in a smaller place.
30	 */
31	
32	import { useCallback, useRef } from "react";
33	import { inDays } from "../graph/wires/encodings";
34	import type { LinkView } from "../world";
35	import { alongWire, inColumn, type PositionMap, stepThrough } from "./focusMap";
36	
37	/** What the keys that are not about moving are wired to. */
38	export interface MapKeys {
39	  /** `E` — the six things you can do to the focused claim. */
40	  readonly intervene: () => void;
41	  /** `B` — start a branch from here. */
42	  readonly branch: () => void;
43	  /** `Space` — flip between the two maps, as a hard switch. */
44	  readonly flipWorlds: () => void;
45	  /** `O` — read the map as a list. */
46	  readonly outline: () => void;
47	  /** `P` — show or hide the panel beside the map. */
48	  readonly panel: () => void;
49	  /** `⌘K` — every command, by name. */
50	  readonly palette: () => void;
51	}
52	
53	/** What the key handler needs to know about the map it is on. */
54	export interface MapKeysNeeds {
55	  /** Every arrow on the map, feedback arrows included: this is walking, not moving numbers. */
56	  readonly wires: readonly LinkView[];
57	  /** Where every tile ended up. */
58	  readonly positions: PositionMap;
59	  /** Which claim the keyboard is on. */
60	  readonly focused: string | null;
61	  /** Put the keyboard on a claim. */
62	  readonly onFocused: (id: string) => void;
63	  /** Say what the last keystroke did. */
64	  readonly onStatus: (line: string) => void;
65	  /** Everything the keys that are not about moving are wired to. */
66	  readonly keys: MapKeys;
67	  /** What a claim is called, for the line under the map. */
68	  readonly words: (id: string) => string;
69	}
70	
71	/**
72	 * How a wire reads in the line under the map.
73	 *
74	 * It names the kind of push rather than the identifier, because the identifier
75	 * says nothing and the kind is what decides whether the step you just took was
76	 * the one you meant.
77	 */
78	function wireInWords(wire: LinkView): string {
79	  const kind = wire.reflexive
80	    ? "the feedback arrow"
81	    : wire.mode === "sustain"
82	      ? "an arrow that only holds while its cause holds"
83	      : "an arrow that fires once and fades";
84	  return `along ${kind} · ${inDays(wire.lag)}`;
85	}
86	
87	/**
88	 * Bind the keyboard map to the map surface.
89	 *
90	 * @returns The handler to put on the surface, and a way to clear the set that a
91	 *   sideways step left behind.
92	 */
93	export function useMapKeys(needs: MapKeysNeeds) {
94	  // The neighbours a sideways step passed over. They become the up-and-down set
95	  // where you land, so nothing on the map is more than two keystrokes away and
96	  // there is no chooser overlay — which would be a pop-up in all but name.
97	  const leftOver = useRef<{ at: string; others: readonly string[] } | null>(null);
98	
99	  const { wires, positions, focused, onFocused, onStatus, keys, words } = needs;
100	
101	  /**
102	   * Where the keyboard is **now**, which is not always where the last render
103	   * said it was.
104	   *
105	   * This handler moves the keyboard itself, synchronously: by the time it
106	   * returns, the tile it moved to already has focus. The value it was handed,
107	   * `focused`, is state, and state lands a render later. So two keys pressed
108	   * inside one frame — a reader typing quickly, or a machine slow enough to
109	   * deliver two keydowns in a single task — were **both** worked out from the
110	   * claim the reader was on before the first one. The second key then did
111	   * nothing at all, and the map said *"nothing causes this claim on this map"*
112	   * about a claim with three causes.
113	   *
114	   * So the handler keeps its own note of where it put the keyboard, and follows
115	   * `focused` whenever that changes for a reason other than its own move: Tab,
116	   * a click, a branch opening on the claim it added.
117	   */
118	  const at = useRef(focused);
119	  const lastSaid = useRef(focused);
120	  if (lastSaid.current !== focused) {
121	    lastSaid.current = focused;
122	    at.current = focused;
123	  }
124	
125	  return useCallback(
126	    (event: KeyboardEvent): void => {
127	      /** Move the keyboard, and remember it now rather than a render from now. */
128	      const moveTo = (id: string): void => {
129	        at.current = id;
130	        onFocused(id);
131	      };
132	
133	      const target = event.target as HTMLElement;
134	      const typing =
135	        target.tagName === "INPUT" ||
136	        target.tagName === "TEXTAREA" ||
137	        target.isContentEditable === true;
138	      if (typing) {
139	        return;
140	      }
141	
142	      const upDown = (way: 1 | -1): void => {
143	        const from = at.current;
144	        if (from === null) {
145	          return;
146	        }
147	        const set =
148	          leftOver.current?.at === from && leftOver.current.others.length > 0
149	            ? [from, ...leftOver.current.others]
150	            : inColumn(from, positions);
151	        const landed = stepThrough(from, set, positions, way);
152	        if (landed === null) {
153	          onStatus(way === 1 ? "last claim in this column" : "first claim in this column");
154	          return;
155	        }
156	        moveTo(landed);
157	        onStatus(`${way === 1 ? "down" : "up"} the column · ${words(landed)}`);
158	      };
159	
160	      const sideways = (way: "in" | "out"): void => {
161	        const from = at.current;
162	        if (from === null) {
163	          return;
164	        }
165	        const step = alongWire(from, way, wires, positions);
166	        if (step === null) {
167	          onStatus(
168	            way === "out"
169	              ? "nothing follows from this claim — it is where the chain ends"
170	              : "nothing causes this claim on this map",
171	          );
172	          return;
173	        }
174	        leftOver.current = { at: step.to, others: step.others };
175	        moveTo(step.to);
176	        onStatus(`${wireInWords(step.wire)} · ${words(step.to)}`);
177	      };
178	
179	      // Every command, by name. Checked before the plain letters, or a k with the
180	      // command key held would walk down a column instead.
181	      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
182	        event.preventDefault();
183	        keys.palette();
184	        return;
185	      }
186	      if (event.metaKey || event.ctrlKey || event.altKey) {
187	        return;
188	      }
189	
190	      switch (event.key) {
191	        case "j":
192	          event.preventDefault();
193	          upDown(1);
194	          return;
195	        case "k":
196	          event.preventDefault();
197	          upDown(-1);
198	          return;
199	        case "h":
200	          event.preventDefault();
201	          sideways("in");
202	          return;
203	        case "l":
204	          event.preventDefault();
205	          sideways("out");
206	          return;
207	        case "E":
208	        case "e":
209	          event.preventDefault();
210	          keys.intervene();
211	          onStatus("the six things you can do to this claim, in the panel beside the map");
212	          return;
213	        case "B":
214	        case "b":
215	          event.preventDefault();
216	          keys.branch();
217	          onStatus("name the branch in the panel beside the map");
218	          return;
219	        case "O":
220	        case "o":
221	          event.preventDefault();
222	          keys.outline();
223	          return;
224	        case "P":
225	        case "p":
226	          event.preventDefault();
227	          keys.panel();
228	          return;
229	        case " ":
230	          // Space activates whatever button the keyboard happens to be on, so it
231	          // only flips the two maps when the keyboard is on the map itself.
232	          if (target.closest("button") !== null) {
233	            return;
234	          }
235	          event.preventDefault();
236	          keys.flipWorlds();
237	          return;
238	        default:
239	          return;
240	      }
241	    },
242	    // `focused` is not here on purpose: where the keyboard is is read from the
243	    // note above, which is right as of this keystroke rather than as of the last
244	    // render. Leaving it in would rebuild this handler — and rebind the listener
245	    // carrying it — on every step across the map, for nothing.
246	    [wires, positions, onFocused, onStatus, keys, words],
247	  );
248	}
