/**
 * The whole screen: the launchpad, and the map you open from it.
 *
 * Two states and nothing in between. The launchpad names the two ways into the
 * tool and offers the four examples from the brief; opening the one that is
 * built swaps the page for the map. Everything on the map came over the wire
 * from the server, and the line under it says which address it came from — this
 * product does not put a number on screen that a reader cannot trace to an
 * input, a rule or a source, and that includes numbers a stored example happens
 * to carry.
 *
 * There is no spinner anywhere, and there never will be. A spinner says "wait"
 * without saying what for. While something is on its way the screen says what
 * it is waiting for and where it asked.
 */

import { useCallback, useEffect, useMemo, useState } from "react";
import type { About, FixtureSummary, Health, Readiness } from "./api/client";
import { readAbout, readExampleList, readHealth, readReadiness } from "./api/client";
import type { Asked } from "./components/InputBar";
import { Launchpad } from "./components/Launchpad";
import { MapScreen } from "./components/MapScreen";
import { GenerationScreen } from "./stream/GenerationScreen";
import type { TheRun } from "./stream/theRun";
import { askForAMap } from "./stream/theRun";
import {
  ApiWorldSource,
  type BranchView,
  branchesOf,
  FixtureWorldSource,
  type WorldSource,
  type WorldView,
} from "./world";
import { asOneSentence } from "./world/failures";
import { countInWords } from "./world/naming";

/**
 * Everything the screen can know about one thing it asked for. Three states and
 * no others, which is what makes every pixel below traceable to a cause.
 */
type Answer<Reading> =
  | { state: "asking" }
  | { state: "answered"; value: Reading }
  | { state: "failed"; reason: string };

/** How loud a row's words are. Emphasis only — the words carry the meaning. */
type Tone = "good" | "quiet" | "loud";

/** One row of the strip at the foot of the launchpad. */
interface Reading {
  /** What is being reported, such as "server". */
  label: string;
  /** The value from the server, or null while the request is still in flight. */
  value: string | null;
  /** A mark beside the words. Never the only carrier of meaning. */
  glyph: string;
  /** What the value means, in plain words. On a failure, this is the failure. */
  state: string;
  tone: Tone;
}

/**
 * Ask what this copy can do.
 *
 * Defined at module level because the hook below runs it once and needs the
 * same function on every render.
 *
 * **It reads the generated description of the server and nothing else.** The
 * two fields the first screen lives on — which examples can be played, and one
 * sentence per recording this engine could not read — were written out by hand
 * here for as long as the route that owns them was being built beside this
 * half. They are in `schema.ts` now, so the hand-written copy is gone: two
 * descriptions of one answer eventually disagree, and the generated one is the
 * server's own.
 */
function askReadiness(): Promise<Readiness> {
  return readReadiness();
}

/**
 * Make one request when the screen first appears and report where it got to.
 *
 * @param ask The request to make. It must be the same function on every render,
 *   so pass one defined at module level rather than one written inline.
 */
function useAnswer<Reading>(ask: () => Promise<Reading>): Answer<Reading> {
  const [answer, setAnswer] = useState<Answer<Reading>>({ state: "asking" });

  useEffect(() => {
    let stillOnScreen = true;
    ask().then(
      (value) => {
        if (stillOnScreen) {
          setAnswer({ state: "answered", value });
        }
      },
      (reason: unknown) => {
        if (stillOnScreen) {
          setAnswer({ state: "failed", reason: asOneSentence(reason) });
        }
      },
    );
    return () => {
      stillOnScreen = false;
    };
  }, [ask]);

  return answer;
}

/**
 * Whether the server answered, and which build answered — in one quiet line.
 *
 * **They were two rows of the strip, and they are two facts a reader of this
 * screen is not making a decision about.** A route name and a build number
 * under the first screen make a take-home read as an implementation showcase at
 * the moment it should read as a decision tool. Nothing is lost: both readings
 * are still here, still the server's own, still traceable to the address the
 * line under them names. They are simply not given the weight of a labelled row
 * beside the one reading that changes what a reader can do, which is whether
 * there is a model key.
 *
 * Each half says where it has got to for itself, so a failure of one is not
 * hidden by the other answering.
 *
 * @param health What `/api/healthz` said, or where that question has got to.
 * @param about What `/api/about` said, or where that question has got to.
 */
function serverAndBuild(health: Answer<Health>, about: Answer<About>): string {
  const reachable =
    health.state === "asking"
      ? "Asking the server whether it is there."
      : health.state === "answered"
        ? `Server ${health.value.status}.`
        : health.reason;
  const build =
    about.state === "asking"
      ? "Asking which build answered."
      : about.state === "answered"
        ? `Build ${about.value.version}, reported by ${about.value.name}.`
        : about.reason;
  return `${reachable} ${build}`;
}

/** The row that says whether a key for the language model is configured. */
function modelKeyReading(answer: Answer<Readiness>): Reading {
  switch (answer.state) {
    case "asking":
      return {
        label: "model key",
        value: null,
        glyph: "○",
        state: "asking the server",
        tone: "quiet",
      };
    case "answered":
      return answer.value.model_key_present
        ? {
            label: "model key",
            value: "present",
            glyph: "●",
            state: "ready to generate",
            tone: "good",
          }
        : {
            label: "model key",
            value: "absent",
            glyph: "○",
            state:
              answer.value.replayable.length === 0
                ? "no key configured, and nothing recorded to play instead"
                : `no key configured — ${countInWords(answer.value.replayable.length)} ` +
                  `${answer.value.replayable.length === 1 ? "example plays" : "examples play"} ` +
                  `from recordings`,
            tone: "quiet",
          };
    case "failed":
      return { label: "model key", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
  }
}

/**
 * One row: a label, the value the server gave, and what that value means.
 *
 * While the value is missing the cell holds a bar of the same height, so the
 * row does not change size when the answer arrives. There is no spinner: a bar
 * where the value will land says the same thing without pretending to spin.
 */
function StatusRow({ reading }: { reading: Reading }) {
  const waiting = reading.value === null;
  return (
    <div className="status-row">
      <dt className="status-label">{reading.label}</dt>
      <dd className="status-value" data-settled={waiting ? "no" : "yes"}>
        {waiting ? <span className="placeholder" aria-hidden="true" /> : reading.value}
      </dd>
      <dd className="status-state" data-tone={reading.tone}>
        <span className="glyph" aria-hidden="true">
          {reading.glyph}
        </span>
        <span className="state-words">{reading.state}</span>
      </dd>
    </div>
  );
}

/** Which of the screens is showing. */
type Screen =
  | { at: "launchpad" }
  | { at: "opening"; id: string }
  /**
   * A map being built in front of the reader, from a sentence they typed.
   *
   * **The run is here, not inside the screen**, because the press that made this
   * state is what asked for it. A screen that asked on mount would ask twice in
   * development, where React mounts every screen, unmounts it and mounts it
   * again on purpose — and *"never retry, a generation that ran twice would
   * spend twice"* would be broken on every machine this product is built on.
   */
  | { at: "growing"; run: TheRun }
  | {
      at: "map";
      world: WorldView;
      branches: readonly BranchView[];
      /**
       * Why the map on screen was read from the stored example rather than
       * worked out by the engine, or nothing when the engine answered.
       */
      insteadOfTheEngine: string | null;
    }
  | { at: "failed"; id: string; reason: string };

/**
 * Where maps come from: the engine.
 *
 * Every number on the map is worked out by it, from the stored map, the branch
 * and one seed. Nothing on this screen computes a likelihood, and nothing on
 * this screen shows one the engine did not produce.
 */
const DEFAULT_SOURCE: WorldSource = new ApiWorldSource();

/**
 * Where maps come from when the engine cannot be reached.
 *
 * A map you can still read beats a blank screen. The stored example's claims,
 * arrows, dates and sources are all real and all still worth reading — what is
 * missing is the working-out, and the screen says so in a line under the map
 * rather than letting a hand-written likelihood pass for a computed one.
 */
const FALLBACK_SOURCE: WorldSource = new FixtureWorldSource();

/**
 * The line under the map when the stored example is standing in for the engine.
 *
 * @param reason What went wrong, in the sentence the failure arrived with.
 */
function insteadOfTheEngine(reason: string): string {
  return (
    `The engine did not answer, so this map is the stored example exactly as it was written: ` +
    `its claims, arrows, dates and sources are real, and its likelihoods are the illustrative ` +
    `ones somebody wrote down rather than anything worked out. ${reason}`
  );
}

/** What the screen needs. All three have defaults; all three exist so they can be swapped. */
export interface AppProps {
  /** Where maps and worlds come from. */
  readonly source?: WorldSource;
  /** Where they come from when the first one cannot answer. */
  readonly fallback?: WorldSource;
  /** How the list of stored examples is read. */
  readonly listExamples?: () => Promise<FixtureSummary[]>;
}

/** The screen. */
export function App({
  source = DEFAULT_SOURCE,
  fallback = FALLBACK_SOURCE,
  listExamples = readExampleList,
}: AppProps = {}) {
  const health = useAnswer(readHealth);
  const readiness = useAnswer(askReadiness);
  const about = useAnswer(readAbout);
  const examples = useAnswer(listExamples);

  const [screen, setScreen] = useState<Screen>({ at: "launchpad" });
  const [using, setUsing] = useState<WorldSource>(source);

  const open = useCallback(
    (id: string) => {
      setScreen({ at: "opening", id });
      /**
       * The world and the map's own branches, together: the world is what gets
       * drawn, and the branches are the edits somebody already made to it, which
       * the panel lists and the diff view folds on.
       *
       * @param from Where to ask.
       */
      const ask = (from: WorldSource) =>
        Promise.all([from.readWorld({ baseId: id }), from.readBundle(id)]);

      ask(source).then(
        ([world, bundle]) => {
          setUsing(source);
          setScreen({ at: "map", world, branches: branchesOf(bundle), insteadOfTheEngine: null });
        },
        (failure: unknown) => {
          // The engine could not answer. Rather than a blank screen, the stored
          // example — and a line under the map saying, in the failure's own
          // words, that these are not computed numbers.
          ask(fallback).then(
            ([world, bundle]) => {
              setUsing(fallback);
              setScreen({
                at: "map",
                world,
                branches: branchesOf(bundle),
                insteadOfTheEngine: insteadOfTheEngine(asOneSentence(failure)),
              });
            },
            // Neither answered, which means the server itself is not there. That
            // is one sentence on the page, and a way back to the launchpad.
            (alsoFailed: unknown) =>
              setScreen({ at: "failed", id, reason: asOneSentence(alsoFailed) }),
          );
        },
      );
    },
    [source, fallback],
  );

  const toLaunchpad = useCallback(() => setScreen({ at: "launchpad" }), []);

  /**
   * Build a map from a sentence, and watch it arrive.
   *
   * **The request goes from here**, inside the press. Not from a render and not
   * from an effect: an effect runs twice in development by design, and this is
   * the one request in the product where running twice means paying twice.
   */
  const build = useCallback((asked: Asked) => {
    setScreen({ at: "growing", run: askForAMap(asked) });
  }, []);

  /**
   * Leave a generation: let go of it first, then go back.
   *
   * Letting go is what stops the spending — the route checks whether the client
   * is still there before its next model call — and it is done here, in the
   * press, rather than when the screen unmounts, for the same reason the run is
   * started in a press: a development-mode unmount would stop a run nobody left.
   */
  const leaveTheRun = useCallback(
    (run: TheRun) => () => {
      run.letGo();
      setScreen({ at: "launchpad" });
    },
    [],
  );

  /** Ask the same question again, which is a new run and a new screen. */
  const runAgain = useCallback(
    (run: TheRun) => () => {
      run.letGo();
      setScreen({ at: "growing", run: askForAMap(run.asked) });
    },
    [],
  );

  // **One labelled row, and one quiet line.** The row is the model key, because
  // it is the one reading on this screen that changes what a reader can do — it
  // is why a sentence has a recording behind it or nothing at all. Whether the
  // server answered and which build answered are still here, in the line under
  // it, where they are traceable without being the first thing read.
  const readings = useMemo(() => [modelKeyReading(readiness)], [readiness]);
  const behind = useMemo(() => serverAndBuild(health, about), [health, about]);

  if (screen.at === "growing") {
    return (
      <GenerationScreen
        // Named by the press that asked for it, so that asking the same question
        // again draws a fresh screen rather than a second map inside the first
        // one's selection and focus.
        key={screen.run.press}
        run={screen.run}
        // Known before the stream has said anything, which is the whole reason
        // the badge can be on screen from the first frame. When the receipt
        // arrives it is the authority, and the badge takes its word.
        replaying={readiness.state === "answered" && !readiness.value.model_key_present}
        onRunAgain={runAgain(screen.run)}
        onLeave={leaveTheRun(screen.run)}
      />
    );
  }

  if (screen.at === "map") {
    return (
      <MapScreen
        base={screen.world}
        branches={screen.branches}
        source={using}
        insteadOfTheEngine={screen.insteadOfTheEngine}
        onLeave={toLaunchpad}
      />
    );
  }

  if (screen.at !== "launchpad") {
    return (
      <main className="page page--map">
        <header className="map-bar">
          <button className="map-bar__back" type="button" onClick={toLaunchpad}>
            <span aria-hidden="true">←</span> Back to the launchpad
          </button>
          <h1 className="map-bar__title">Strait of Hormuz</h1>
        </header>

        <div className="map-waiting">
          <p className="map-waiting__line">
            {screen.at === "opening"
              ? `Reading the map from /api/fixtures/${screen.id} and asking /api/worlds to work ` +
                `its likelihoods through.`
              : screen.reason}
          </p>
        </div>
      </main>
    );
  }

  return (
    <main className="page">
      {/* The first screen is the one wide column in this product: it holds the
          two doors, a map that is already drawn, the four sentences from the
          brief and the field you type your own into, and stacking all of that
          in the 660-pixel measure the rest of the page reads at pushes the
          field below the fold. `launchpad.css` owns the width. */}
      <div className="column column--launchpad">
        <header className="masthead">
          <h1 className="wordmark">Katalyst</h1>
          <p className="purpose">
            Type an event you think will happen. See what it would cause, step by step, ending in
            trades.
          </p>
        </header>

        <Launchpad
          examples={examples.state === "answered" ? examples.value : null}
          failure={examples.state === "failed" ? examples.reason : null}
          readiness={readiness.state === "answered" ? readiness.value : null}
          // **An absent answer is two different facts and the screen is handed
          // both.** Without this, a readiness request that failed looked exactly
          // like one still in flight, and the first screen said *asking the
          // server* for ever over an ask that had ended — while the strip below
          // it printed the failure's own sentence. A screen asserting a question
          // that is not being asked is a state nobody can trace to an input.
          readinessFailure={readiness.state === "failed" ? readiness.reason : null}
          onOpen={open}
          onBuild={build}
        />

        <section aria-labelledby="status-heading">
          <h2 className="section-heading" id="status-heading">
            What this build can do right now
          </h2>
          <dl className="status-strip">
            {readings.map((reading) => (
              <StatusRow key={reading.label} reading={reading} />
            ))}
          </dl>
          <p className="provenance">{behind}</p>
          <p className="provenance">
            Every reading above came from the server, at <code>/api/healthz</code>,{" "}
            <code>/api/readyz</code> and <code>/api/about</code>. The examples came from{" "}
            <code>/api/fixtures</code>. Nothing on this screen is written into the page.
          </p>
        </section>
      </div>
    </main>
  );
}

/**
 * The frame both map screens are drawn in, written once.
 *
 * A stored map and a map building itself are two different things — one is read
 * and edited, the other arrives claim by claim — but the screen around them is
 * the same screen, and it was written twice. A bar with the way back and the
 * map's name; the map filling everything under it, with whatever opens over the
 * stage and one line saying what the last keystroke did; the panel beside it in
 * the frame that carries the *there is more this way* rules; one polite line
 * said out loud; and, at the foot, where every number on this map came from.
 *
 * Two copies of that drifted the moment either was improved. The panel's frame
 * landed on one screen a round before the other; the error boundary landed on
 * one and not the other at all. **A reader who has learned one of these screens
 * has learned the other**, and that is a promise about the code as much as
 * about the picture: there is one screen here, and two things put into it.
 *
 * **It owns the panel's own measuring**, because the rules it draws are a fact
 * about the frame rather than about what either screen put in the panel — see
 * `useTheEdges.ts` for why they are drawn on the frame and never inside the box
 * they measure.
 *
 * **And it owns the one error boundary.** A fault while drawing a map that
 * arrived in a shape nothing expected takes the map down and leaves the bar
 * standing, which is the way back to the launchpad. React's own answer is to
 * unmount the whole tree, and a reader three minutes into a generation would be
 * left with a white page.
 */

import type { ReactNode } from "react";
import { IfTheScreenBreaks } from "./IfTheScreenBreaks";
import { edgeMarks, useTheEdgesOfThePanel } from "./useTheEdges";

/** What the frame needs. Every slot is a thing one of the two screens fills. */
export interface MapFrameProps {
  /** The map's name, in the bar. */
  readonly title: string;
  /**
   * What sits between the name and *Every key* — which branch you are in, or
   * which door this generation came through.
   */
  readonly where: ReactNode;
  /** Let this map go. On a generation it is also what stops the spending. */
  readonly onLeave: () => void;
  /** Open the sheet of every key. */
  readonly onEveryKey: () => void;
  /** The map itself. */
  readonly map: ReactNode;
  /**
   * Whatever is open over the stage: the palette, the sheet.
   *
   * Over the **stage** and never over the panel, and never over the whole
   * screen: there are no pop-ups anywhere in this product, and the panel is
   * what makes the map mean anything.
   */
  readonly overlay?: ReactNode;
  /** What the last keystroke did, under the map. */
  readonly status: string;
  /** The panel beside the map, or nothing when the reader has put it away. */
  readonly panel: ReactNode;
  /** The one line said out loud. Empty says nothing rather than saying nothing loudly. */
  readonly saying: string;
  /**
   * True when that line is spoken only.
   *
   * A generated map draws the same facts on the canvas, in the panel and under
   * the map, so printing them again made the foot of the screen three strips of
   * prose saying one thing three times. A stored map prints it, because nothing
   * else on that screen says what an edit just did.
   */
  readonly spokenOnly?: boolean;
  /** Where every number on this map came from, and anything still on its way. */
  readonly origin: ReactNode;
}

/** A map, and the screen around it. */
export function MapFrame({
  title,
  where,
  onLeave,
  onEveryKey,
  map,
  overlay,
  status,
  panel,
  saying,
  spokenOnly = false,
  origin,
}: MapFrameProps) {
  const { panel: scroller, edges } = useTheEdgesOfThePanel();

  const bar = (
    <header className="map-bar">
      <button className="map-bar__back" type="button" onClick={onLeave}>
        <span aria-hidden="true">←</span> Back to the launchpad
      </button>
      <h1 className="map-bar__title">{title}</h1>
      {where}
      <button className="map-bar__sheet" type="button" onClick={onEveryKey}>
        Every key (?)
      </button>
    </header>
  );

  return (
    <main className="page page--map">
      <IfTheScreenBreaks header={bar}>
        {/* The map and the panel, side by side. The panel is part of the screen
            rather than something that appears over it: there are no pop-ups
            anywhere in this product, and a dialog you have to dismiss would
            steal the map that makes the detail mean anything. */}
        <div className="map-body">
          <div className="map-stage">
            {map}
            {overlay}
            <p className="map-status">
              <span className="map-status__mark">last key</span>
              {status}
            </p>
          </div>

          {panel === null ? null : (
            // The frame holds the two rules that say there is more above or
            // more below. They are drawn on it rather than inside the panel so
            // that turning one on cannot change the scroll height it was worked
            // out from — see `useTheEdges.ts`.
            <div className="dock-frame" {...edgeMarks(edges)}>
              <aside className="dock" ref={scroller} aria-label="The panel beside the map">
                {panel}
              </aside>
            </div>
          )}
        </div>

        {/* Said out loud for a reader who is not looking at the picture.
            Polite: it waits for a pause rather than cutting across whatever is
            being read. */}
        <p className={spokenOnly ? "map-live map-live--spoken" : "map-live"} aria-live="polite">
          {saying}
        </p>

        {/* Where every number on this map came from, and anything that is still
            on its way. There is no spinner here and never will be: a spinner
            says "wait" without saying what for, so the line says what has been
            asked and at which address, and the map keeps drawing the last
            answer while it waits. */}
        <div className="map-origin">{origin}</div>
      </IfTheScreenBreaks>
    </main>
  );
}

/**
 * The first screen: what you can start from, and the two ways in.
 *
 * No illustration and no empty box staring back. The two doors are named and
 * explained in a line each, the stored example opens a map that is already drawn,
 * and the four sentences from the brief each build one in front of you.
 *
 * **A card is only ever something you can take up.** It runs live or it runs
 * from a recording. A sentence this copy can do neither with gets no card at
 * all: it is named, with the others in its position, in the one line under the
 * cards that says what this copy can play. Three headstones beside one door,
 * taking the whole of the right-hand column, is what a reviewer with thirty
 * minutes met before — and *not yet live* on a row you cannot press is a
 * control a reader counted and cannot use.
 *
 * **Six states, and each says a different true thing.** They are listed here
 * because the two that look alike are the ones this screen got wrong twice: an
 * answer that has not arrived and an answer that never will.
 *
 * | What is true | What the screen shows |
 * |---|---|
 * | The readiness ask is in flight | Every sentence, each reading *Asking the server whether this one can be run here: whether a model key is configured, and whether there is a recording of it to play.* |
 * | The readiness ask did not come back | Every sentence, each reading *The ask did not come back, so nothing is known about whether this one can be run here*, and the server's own sentence once, under them |
 * | A model key is configured | Every sentence, as a card that runs live |
 * | No key, and this one has a recording | A card that plays it, badged *replay*, with the day it was made |
 * | No key, and this one has no recording | **No card.** The line under the cards names it with the others in its position |
 * | No key, and nothing at all is recorded | **No cards.** One line saying so, pointing at the map that is already drawn, which needs neither |
 *
 * The last three are one rule and not three: a card for everything this copy
 * can do. The first two are two rules on purpose, because a question in flight
 * invites waiting and an ask that got no reply invites asking again.
 *
 * **With no key, the four run from recordings through the same route, the same
 * eight events and the same canvas.** The sentence that says so is record 0012's,
 * word for word, and the day in it is read from the server's own readiness answer
 * — never from a file name, never from a build date, never from the browser's own
 * clock. Where the four were not all recorded on one day, the shared sentence
 * names the **oldest** day in the set and each card carries its own, so the
 * sentence is never more current than the oldest thing it describes.
 *
 * **This screen reads what can be replayed and whether a key is configured, and
 * ignores whether the server called itself ready.** A program with no key but
 * four recordings can do everything a reviewer came to see, and a card greyed out
 * because the whole server called itself not ready would be the most misleading
 * screen in the product.
 */

import type { FixtureSummary, Readiness } from "../api/client";
import { countInWords } from "../world/naming";
import type { Asked } from "./InputBar";
import { InputBar } from "./InputBar";
import "./launchpad.css";

/** One of the two ways into the tool. */
interface Door {
  readonly name: string;
  readonly line: string;
}

/**
 * The two doors, from the requirements: start from an event and follow it out,
 * or name where you think it ends and ask whether the chain really gets there.
 */
const DOORS: readonly Door[] = [
  {
    name: "Explore",
    line: "Start from an event and see what it would cause, out to the things you could trade.",
  },
  {
    name: "Verify",
    line: "Name where you think it ends, and see whether a chain really gets there — or that none does.",
  },
];

/** One of the four sentences from the brief, and which recording answers to it. */
export interface StartingSentence {
  /**
   * Which stored example this is.
   *
   * It is the name the readiness answer uses for a recording, so that a card can
   * say whether there is one to play. It is **not** a file name and it never
   * reaches a request: what a card sends is its sentence, exactly as a reader
   * would type it, which is what makes the replayed path and the live path send
   * byte-identical requests.
   */
  readonly example: string;
  /** The sentence, as a person would actually type it. */
  readonly sentence: string;
  /**
   * What this example is about, in two or three words.
   *
   * **It is how a sentence with no card of its own is still named.** A line
   * reading *the other three have nothing recorded yet* points at three
   * sentences that are no longer on the screen, which leaves a reader counting
   * what is missing rather than being told. The short name is authored here,
   * beside the sentence it belongs to, and it is not the recording's short name
   * (`hormuz`, `export-controls`): those are identifiers that name a file and a
   * card and an eval case, and an identifier is never words on the screen.
   */
  readonly about: string;
}

/** The four examples from the brief, in the order the brief lists them. */
export const STARTING_SENTENCES: readonly StartingSentence[] = [
  {
    example: "hormuz",
    sentence: "The Strait of Hormuz is going to open next week.",
    about: "the strait",
  },
  {
    example: "midterms",
    sentence: "Republicans win the House but Democrats take the Senate during the midterms.",
    about: "the midterms",
  },
  {
    example: "export-controls",
    sentence: "Models more capable than Fable get export restricted by the United States.",
    about: "export controls",
  },
  {
    example: "photonics",
    sentence: "Photonic chips get adopted faster than expected.",
    about: "photonic chips",
  },
];

/**
 * A few things, listed the way a sentence lists them: *a, b and c*.
 *
 * @param things What to list, in the order they should be read.
 */
export function asAList(things: readonly string[]): string {
  if (things.length <= 1) {
    return things[0] ?? "";
  }
  return `${things.slice(0, -1).join(", ")} and ${things[things.length - 1]}`;
}

/**
 * Record 0012's sentence, word for word, with the day the readiness answer gave.
 *
 * **It is printed only when it is true**: when all four of the sentences below
 * can be played and all four were recorded on the same day. Anything else and it
 * would be a screen claiming something a reader can see is false — three cards
 * reading *not yet live* under a line saying these four run from recordings — and
 * the one screen this product cannot afford to be caught out on is the one that
 * exists to say what this copy can honestly do.
 *
 * @param day The day the recordings were made.
 */
export function keylessSentence(day: string): string {
  return `No model key configured — these four run from recordings made on ${day}.`;
}

/**
 * What this copy can play, in one or two sentences, and always true.
 *
 * Four shapes, and the first is record 0012's own words. The others say the same
 * kind of thing in the same voice: how many of the four can be played, how many
 * cannot, and the day — the **oldest** day, where there is more than one, so the
 * sentence is never more current than the oldest thing it describes.
 *
 * **The ones that cannot be played are named**, because they have no card to be
 * seen on: a line reading *the other three have nothing recorded yet* points at
 * three sentences that are no longer on the screen, and a reader counting what
 * is missing is a reader being asked to do the screen's work.
 *
 * @param days The day each playable example was recorded on, in any order.
 * @param missing What each example with no recording is about, in a few words,
 *   in the order the screen offers them.
 */
export function whatThisCopyCanPlay(
  days: readonly string[],
  missing: readonly string[],
): string | null {
  if (days.length === 0) {
    return null;
  }
  const outOf = days.length + missing.length;
  const sorted = [...days].sort();
  const oldest = sorted[0] as string;
  const oneDay = sorted[sorted.length - 1] === oldest;

  if (missing.length === 0 && oneDay) {
    return keylessSentence(oldest);
  }
  if (missing.length === 0) {
    return (
      `No model key configured — these ${countInWords(outOf)} run from recordings, the oldest ` +
      `made on ${oldest}.`
    );
  }
  const canPlay = days.length === 1 ? "runs" : "run";
  const cannot = missing.length === 1 ? "has" : "have";
  const when = oneDay ? `made on ${oldest}` : `the oldest made on ${oldest}`;
  return (
    `No model key configured — ${countInWords(days.length)} of these ${countInWords(outOf)} ` +
    `${canPlay} from recordings, ${when}; ${asAList(missing)} ${cannot} nothing recorded yet.`
  );
}

/**
 * What this copy can do with one of the brief's sentences.
 *
 * **Five, and two of them never draw a card.** An example this copy can neither
 * run nor play is not a card a reader can take up, and three of those side by
 * side under a heading offering to build you a map is a graveyard with a door in
 * it. What is left of them is one quiet line under the cards that do work,
 * naming which they are — which is the same sentence that was already printed
 * there, in `whatThisCopyCanPlay`.
 *
 * **`asking` and `no-answer` are the two states before there is anything to
 * say**, and they are two states rather than one because they invite different
 * things. *Asking* is a question in flight and it will answer; *the ask did not
 * come back* is the server there and one attempt that got no reply, which stops
 * being true the moment somebody asks again. Collapsing them was the defect this
 * type exists to prevent: with them folded together a failed request left the
 * screen saying *asking the server* for ever, which is a screen asserting
 * something that is not happening.
 */
type CardState = "live" | "replay" | "not-yet" | "asking" | "no-answer";

/** What the launchpad needs to draw itself. */
export interface LaunchpadProps {
  /**
   * The stored examples the server ships with, or null while the answer is still
   * on its way.
   */
  readonly examples: readonly FixtureSummary[] | null;
  /** Why the list could not be read, if it could not be. */
  readonly failure: string | null;
  /**
   * What the server said about itself: whether a key is configured, and what it
   * can play back. Null while that answer is still on its way **or did not come
   * back at all** — which of the two is what `readinessFailure` says.
   */
  readonly readiness: Readiness | null;
  /**
   * Why the server could not be asked what this copy can do, if it could not be.
   *
   * **Null is not "still asking".** A request that failed and a request in
   * flight are both an absent answer, and a screen that cannot tell them apart
   * says *asking the server* for ever over an ask that ended minutes ago. The
   * sentence here is the failure's own, printed as it came.
   */
  readonly readinessFailure?: string | null;
  /** Open a stored example's map, already drawn. */
  readonly onOpen: (id: string) => void;
  /** Build a map from a sentence. */
  readonly onBuild: (asked: Asked) => void;
}

/** The first screen. */
export function Launchpad({
  examples,
  failure,
  readiness,
  readinessFailure = null,
  onOpen,
  onBuild,
}: LaunchpadProps) {
  // The two facts this screen reads, and the one it deliberately does not.
  const hasKey = readiness?.model_key_present === true;
  const recorded = new Map(
    (readiness?.replayable ?? []).map((one) => [one.example, one.recording_date]),
  );
  // The day each of the four sentences was recorded on, for the ones that were.
  // Read off the cards rather than off the whole answer, so a recording of
  // something this screen does not offer cannot make its sentence wrong.
  const playable = STARTING_SENTENCES.map((one) => recorded.get(one.example)).filter(
    (day): day is string => day !== undefined,
  );
  const canPlay = whatThisCopyCanPlay(
    playable,
    STARTING_SENTENCES.filter((one) => !recorded.has(one.example)).map((one) => one.about),
  );
  const stateOf = (example: string): CardState =>
    readinessFailure !== null
      ? "no-answer"
      : readiness === null
        ? "asking"
        : hasKey
          ? "live"
          : recorded.has(example)
            ? "replay"
            : "not-yet";
  // The sentences that get a card: the ones this copy can actually do something
  // with, and — while nothing is known about any of them — all of them. The rest
  // are named in one line under the cards rather than drawn as rows nobody can
  // press.
  const shown = STARTING_SENTENCES.filter((one) => stateOf(one.example) !== "not-yet");

  return (
    <div className="launchpad">
      <section className="launchpad__doors" aria-labelledby="doors-heading">
        <h2 className="section-heading" id="doors-heading">
          Two ways in
        </h2>
        <ul className="doors">
          {DOORS.map((door) => (
            <li className="door" key={door.name}>
              <span className="door__name">{door.name}</span>
              <span className="door__line">{door.line}</span>
            </li>
          ))}
        </ul>
      </section>

      <section className="launchpad__drawn" aria-labelledby="examples-heading">
        <h2 className="section-heading" id="examples-heading">
          A map that is already drawn
        </h2>
        <ul className="examples">
          {examples === null ? (
            <li className="example example--waiting">
              <span className="example__claim">
                {failure ?? "Asking the server which examples it ships with."}
              </span>
              {failure === null ? <span className="placeholder" aria-hidden="true" /> : null}
            </li>
          ) : (
            examples.map((example) => (
              <li key={example.id}>
                <button
                  className="example example--live"
                  type="button"
                  onClick={() => onOpen(example.id)}
                >
                  <span className="example__claim">{example.title}</span>
                  <span className="example__line">{example.one_line}</span>
                  <span className="example__action">Open the map</span>
                </button>
              </li>
            ))
          )}
        </ul>
      </section>

      <section className="launchpad__build" aria-labelledby="build-heading">
        <h2 className="section-heading" id="build-heading">
          Or watch one build itself
        </h2>
        {/* **Only what this copy can actually do gets a card.** The four
            sentences used to be four cards whatever the answer was, and with one
            recording committed that is one door and three headstones taking the
            whole of this column. What is left of the three is the line under the
            cards, which already named them.

            With nothing at all to offer there is no list, because an empty list
            under a heading that says *or watch one build itself* is worse than
            a sentence saying so. */}
        {shown.length === 0 ? (
          <p className="launchpad__keyless">
            {`No model key configured, and nothing recorded — so ` +
              `${asAList(STARTING_SENTENCES.map((one) => one.about))} cannot be shown building ` +
              `here. The map above is already drawn and needs neither.`}
          </p>
        ) : (
          <ul className="examples">
            {shown.map((one) => {
              const state = stateOf(one.example);
              const day = recorded.get(one.example);
              return (
                <li key={one.example}>
                  {state === "asking" || state === "no-answer" ? (
                    // **Nothing is known about this sentence, and the two ways
                    // of not knowing are told apart.** Before the server has
                    // answered, neither a key nor a recording is known, and
                    // saying either would be the screen asserting something
                    // nobody told it. After an ask that did not come back, the
                    // same is true and *asking the server* would be worse than
                    // silence: it says a question is in flight when none is. The
                    // words are the shared vocabulary's own for the two, and the
                    // server's own sentence is under the cards, once.
                    <div className="example example--waiting" data-state={state}>
                      <span className="example__claim">{one.sentence}</span>
                      <span className="example__line">
                        {state === "asking"
                          ? "Asking the server whether this one can be run here: whether a model key is configured, and whether there is a recording of it to play."
                          : "The ask did not come back, so nothing is known about whether this one can be run here."}
                      </span>
                    </div>
                  ) : (
                    <button
                      className="example example--live"
                      type="button"
                      data-state={state}
                      onClick={() =>
                        onBuild({ hypothesis: one.sentence, target: null, belief: null })
                      }
                    >
                      <span className="example__claim">{one.sentence}</span>
                      <span className="example__line">
                        {state === "replay"
                          ? "Plays the recording of this run back, claim by claim, through the same route and the same canvas."
                          : "Builds a map of what it would cause, claim by claim, ending in trades."}
                      </span>
                      {/* Not **Build the map**: that is the one button on the
                          input bar, and a word that names two controls names
                          neither. A card is a sentence somebody already typed. */}
                      <span className="example__action">
                        {state === "replay" ? (
                          <>
                            <span className="example__badge">replay</span>
                            {day === undefined ? "Watch it build" : `recorded ${day}`}
                          </>
                        ) : (
                          "Watch it build"
                        )}
                      </span>
                    </button>
                  )}
                </li>
              );
            })}
          </ul>
        )}

        {/* Record 0012's sentence, word for word, under the cards — and again
            under the field below, which is disabled with it. It is also what
            names the sentences that have no card: *…the other three have
            nothing recorded yet* is the whole of what there is to say about
            them, and it was already being said here. */}
        {canPlay === null || hasKey || readinessFailure !== null ? null : (
          <p className="launchpad__keyless">{canPlay}</p>
        )}
        {/* **The server's own sentence, once, under the cards that cannot say
            what they are.** It is printed here rather than on each of them
            because it is one fact about this copy and not four facts about four
            examples — and it says what to do about it, which is what tells an
            ask that did not come back apart from an answer that said no. */}
        {readinessFailure === null ? null : (
          <p className="launchpad__keyless">
            {`${readinessFailure} This page asks once: reload it to ask again. Until it answers, nothing here is offered as if it could run.`}
          </p>
        )}
        {/* **A recording that would not play is named, in the server's own
            sentence.** A reviewer who put a file in the recordings folder and
            then counts three cards where they expected four is owed the reason
            rather than left to wonder whether they put it in the wrong place —
            and a recording is a committed file that outlives the code that
            wrote it, so meeting one this engine cannot read is ordinary. It is
            quiet, under the cards, because it is about the copy rather than
            about the maps: the cards that do play are unaffected, which is the
            other half of the same rule. */}
        {(readiness?.unreadable ?? []).map((sentence) => (
          <p className="launchpad__keyless launchpad__keyless--quiet" key={sentence}>
            {sentence}
          </p>
        ))}
      </section>

      {/* A sentence of the reader's own. It is a section of its own rather than
          a footnote under the four cards, because typing your own event is the
          way in this product is for and the four are the shortcut. */}
      <section className="launchpad__yours" aria-labelledby="yours-heading">
        <h2 className="section-heading" id="yours-heading">
          Or start from a sentence of your own
        </h2>
        <InputBar
          disabledBecause={
            readinessFailure !== null
              ? `${readinessFailure} This page asks once: reload it to ask again. Until it answers, whether a sentence of your own could be turned into a map is not known.`
              : readiness === null
                ? "Asking the server whether a model key is configured. A sentence of your own needs the model, and nothing recorded can stand in for one."
                : hasKey
                  ? null
                  : canPlay === null
                    ? "This copy has no model key and no recordings, so a sentence of your own cannot be turned into a map."
                    : `${canPlay} A sentence of your own needs the model, and there is no recording of one.`
          }
          onBuild={onBuild}
        />
      </section>
    </div>
  );
}

/**
 * The way in: type a sentence, and watch what it would cause.
 *
 * **Three fields, one button, and no more.**
 *
 *   1. The sentence — the hypothesis, in the reader's own words.
 *   2. Where it ends, optional. This is the Verify door, and it is **one extra
 *      field rather than a second screen**.
 *   3. The reader's own likelihood, with an explicit *I don't know* state.
 *
 * **The button is "Build the map", word for word, on both doors.** Not
 * *Generate*, which is the pipeline's word rather than the reader's, and not
 * *Explore* or *Verify*, which are the two doors and are already named by whether
 * the second field has anything in it — a button whose label changed as the
 * reader typed would be a control that moved under them.
 *
 * **"I don't know" is a state of the control, not a value.** It is where the
 * control starts, and while it holds, the request carries **no** likelihood at
 * all — not a `.5`, not a wide band, not a null that something downstream treats
 * as a half. A reader who has not said what they think has not said what they
 * think, and a tool that fills that in for them has invented the one number it
 * had no business inventing.
 *
 * **With no model key the bar is visibly disabled and says why**, in the same
 * sentence the launchpad carries. Never silently inert: a field that takes typing
 * and then does nothing reads as a broken tool, where a field that says why reads
 * as an unfinished one, and only one of those is true.
 *
 * Nothing here computes anything. The three numbers the slider holds are the
 * three the reader put there; keeping them in order is a comparison, and the
 * guard that stops the control posting a certainty is a bound on the track.
 */

import { useId, useState } from "react";
import type { Ranged } from "../world";
import { toReading } from "./BeliefChip";
import "./inputBar.css";

/** What a reader asked for when they pressed the button. */
export interface Asked {
  /** The sentence they typed. Never empty: the button does not work without one. */
  readonly hypothesis: string;
  /** Where they said it ends, or nothing at all on the Explore door. */
  readonly target: string | null;
  /**
   * Their own likelihood, or nothing at all while the control is on *I don't
   * know*. Nothing at all is not a half.
   */
  readonly belief: Ranged | null;
}

/** What the bar needs to draw itself. */
export interface InputBarProps {
  /**
   * Why nothing can be built from a sentence right now, in one sentence, or null
   * when it can.
   *
   * It is read from the server's own answer about itself rather than written into
   * the page, so the reason on screen is the real one.
   */
  readonly disabledBecause: string | null;
  /** Start a generation. */
  readonly onBuild: (asked: Asked) => void;
}

/**
 * The bottom and the top of the track.
 *
 * A likelihood of exactly 1 is a certainty, and this product does not print one:
 * the chip prints `>.99` instead, and a control that could post a `1.0` would
 * make that guard a lie about where the number came from. So the track stops one
 * step short at each end, and every step on it is a two-significant-figure value.
 */
const FLOOR = 0.01;
const CEILING = 0.99;
const STEP = 0.01;

/** Where the three handles start, once the reader turns the control on. */
const OPENING: Ranged = { p: 0.5, lo: 0.3, hi: 0.7 };

/** Keep the three in order: the bottom is never above the number, the top never below it. */
function inOrder(belief: Ranged): Ranged {
  const p = Math.min(CEILING, Math.max(FLOOR, belief.p));
  return {
    p,
    lo: Math.min(p, Math.max(FLOOR, belief.lo)),
    hi: Math.max(p, Math.min(CEILING, belief.hi)),
  };
}

/** The way in. */
export function InputBar({ disabledBecause, onBuild }: InputBarProps) {
  const sentenceId = useId();
  const targetId = useId();
  const [hypothesis, setHypothesis] = useState("");
  const [target, setTarget] = useState("");
  // Null is *I don't know*, and it is where the control starts. It is a state of
  // the control rather than a value, so it is held as the absence of one.
  const [belief, setBelief] = useState<Ranged | null>(null);
  const off = disabledBecause !== null;
  const ready = hypothesis.trim() !== "";

  const handle = (over: Partial<Ranged>): void => {
    setBelief((was) => inOrder({ ...(was ?? OPENING), ...over }));
  };

  return (
    <form
      className="input-bar"
      data-disabled={off ? "yes" : "no"}
      onSubmit={(event) => {
        event.preventDefault();
        if (off || !ready) {
          return;
        }
        onBuild({
          hypothesis: hypothesis.trim(),
          target: target.trim() === "" ? null : target.trim(),
          belief,
        });
      }}
    >
      <div className="input-bar__field">
        <label className="input-bar__label" htmlFor={sentenceId}>
          An event you think will happen
        </label>
        <input
          className="input-bar__text"
          id={sentenceId}
          type="text"
          autoComplete="off"
          disabled={off}
          placeholder="The Strait of Hormuz is going to open next week."
          value={hypothesis}
          onChange={(event) => setHypothesis(event.target.value)}
        />
      </div>

      <div className="input-bar__field">
        <label className="input-bar__label" htmlFor={targetId}>
          Where you think it ends — optional
        </label>
        <input
          className="input-bar__text"
          id={targetId}
          type="text"
          autoComplete="off"
          disabled={off}
          placeholder="A Polymarket contract on Brent below $70"
          value={target}
          onChange={(event) => setTarget(event.target.value)}
        />
        <p className="input-bar__hint">
          Fill this in and the map is graded against it: the route, or a plain statement that none
          reaches it.
        </p>
      </div>

      <fieldset className="input-bar__belief" disabled={off}>
        <legend className="input-bar__label">How likely you think it is</legend>

        {belief === null ? (
          <div className="input-bar__unsaid">
            <p className="input-bar__reading" data-reading="unsaid">
              I don&rsquo;t know
            </p>
            <p className="input-bar__hint">
              Nothing is sent for this. A number put here for you would be the one number on the map
              nobody asked for.
            </p>
            <button
              className="input-bar__say"
              type="button"
              onClick={() => setBelief(inOrder(OPENING))}
            >
              Give my own number
            </button>
          </div>
        ) : (
          <div className="input-bar__track">
            <p className="input-bar__reading" data-reading="said">
              {toReading(belief.p, belief.lo, belief.hi)}
            </p>
            <label className="input-bar__handle">
              <span className="input-bar__handle-name">how likely</span>
              <input
                type="range"
                min={FLOOR}
                max={CEILING}
                step={STEP}
                value={belief.p}
                onChange={(event) => handle({ p: Number(event.target.value) })}
              />
            </label>
            <label className="input-bar__handle">
              <span className="input-bar__handle-name">bottom of the range</span>
              <input
                type="range"
                min={FLOOR}
                max={CEILING}
                step={STEP}
                value={belief.lo}
                onChange={(event) => handle({ lo: Number(event.target.value) })}
              />
            </label>
            <label className="input-bar__handle">
              <span className="input-bar__handle-name">top of the range</span>
              <input
                type="range"
                min={FLOOR}
                max={CEILING}
                step={STEP}
                value={belief.hi}
                onChange={(event) => handle({ hi: Number(event.target.value) })}
              />
            </label>
            <p className="input-bar__hint">
              The range says how sure you are of your own number, not how much the world can move.
              It sits beside the model&rsquo;s and a market&rsquo;s, and is never averaged with
              them.
            </p>
            <button className="input-bar__say" type="button" onClick={() => setBelief(null)}>
              Back to &ldquo;I don&rsquo;t know&rdquo;
            </button>
          </div>
        )}
      </fieldset>

      <div className="input-bar__go">
        <button className="input-bar__build" type="submit" disabled={off || !ready}>
          Build the map
        </button>
        {off ? (
          <p className="input-bar__why">{disabledBecause}</p>
        ) : ready ? null : (
          <p className="input-bar__why">
            Type an event above and this builds a map of what it would cause.
          </p>
        )}
      </div>
    </form>
  );
}

